/**
 * Asserts, against the actually-built production bundle, that only the
 * recording half of the trace feature ships to a browser.
 *
 * This is a boundary the docs make a promise about, so it is checked against
 * the artifact rather than against the import graph as written: an accidental
 * re-export from `lib/core/index.js` would break the promise without changing
 * a single line of the trace code.
 */
import assert from 'assert';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';
import { spawnSync } from 'child_process';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const repoRoot = path.resolve(__dirname, '../..');
const cliPath = path.join(repoRoot, 'bin/avenx.js');

console.log('🧪 Testing the trace runtime/tooling bundle boundary...');

const workDir = fs.mkdtempSync(path.join(os.tmpdir(), 'avenx-trace-bundle-'));

try {
  spawnSync(process.execPath, [cliPath, 'init'], { cwd: workDir, stdio: 'ignore' });
  spawnSync(process.execPath, [cliPath, 'g', 'counter'], { cwd: workDir, stdio: 'ignore' });
  const build = spawnSync(process.execPath, [cliPath, 'build'], { cwd: workDir, encoding: 'utf8' });
  assert.strictEqual(build.status, 0, `build failed:\n${build.stderr}`);

  const bundlePath = path.join(workDir, 'dist/bundle.js');
  assert.ok(fs.existsSync(bundlePath), 'a production bundle was produced');
  const bundle = fs.readFileSync(bundlePath, 'utf8');

  // --- What must ship ---------------------------------------------------

  assert.ok(
    bundle.includes('installTraceRecorder'),
    'the browser recorder ships: it is the half that has to run next to a real bug',
  );

  // --- What must never ship ---------------------------------------------

  // Each needle is a literal unique to one CLI-side module and, being a string,
  // survives minification — unlike a function name, which does not.
  //
  // Note what is deliberately *not* checked: the AVX_R25-R28 message templates
  // do ship, because every diagnostic in Avenx lives in AvenxError.js by
  // convention and that convention is worth more than the few hundred bytes.
  // What must not ship is the code that raises them.
  const forbidden = [
    ['the replay engine', 'A divergence means the recorded session'],
    ['the replay reporter', 'diverged from the recording'],
    ['the test generator', 'Regression test generated by'],
    ['the causal viewer', 'this trace can be exported as a regression test'],
    ['the non-determinism prose', 'depends on wall-clock time'],
    ['the trace store', 'Refusing to save a trace with an unusable id'],
    ['the component loader', 'did not produce a class called'],
    ['the compiler', 'ComponentParser'],
    ['the contract checker', 'is declared'],
  ];

  for (const [label, needle] of forbidden) {
    assert.ok(
      !bundle.includes(needle),
      `${label} must not reach an application bundle (found ${JSON.stringify(needle)})`,
    );
  }

  // A Node builtin in a browser bundle means something from tooling/ leaked in.
  for (const builtin of ['require("fs")', "require('fs')", 'node:fs', 'node:path']) {
    assert.ok(!bundle.includes(builtin), `no Node builtin should appear in the bundle (found ${builtin})`);
  }

  // --- The sidecar sits beside the bundle, not inside it ------------------

  const sidecarPath = path.join(workDir, 'dist/bundle.trace.json');
  assert.ok(fs.existsSync(sidecarPath), 'the source-location sidecar is written');
  const sidecar = JSON.parse(fs.readFileSync(sidecarPath, 'utf8'));
  assert.ok(sidecar.components.Counter, 'the sidecar knows the project component');
  assert.ok(
    !bundle.includes('bundle.trace.json'),
    'and the bundle never references it, so a browser never fetches it',
  );

  const html = fs.readFileSync(path.join(workDir, 'index.html'), 'utf8');
  assert.ok(!html.includes('trace'), 'nor does the scaffolded index.html');

  console.log(
    `✅ Bundle boundary holds (bundle ${(bundle.length / 1024).toFixed(1)} KB, ` +
      `sidecar ${(fs.statSync(sidecarPath).size / 1024).toFixed(2)} KB alongside).`,
  );
} finally {
  fs.rmSync(workDir, { recursive: true, force: true });
}
